export const WORD_GUESS_LIMIT = 6
export const WORD_LENGTH = 5
export const WORD_GAME_START_DATE = '2021-06-19'

export type WordPuzzlePhase = 'playing' | 'won' | 'lost'
export type LetterMark = 'correct' | 'present' | 'absent'

export interface WordGuess {
  word: string
  marks: LetterMark[]
}

export interface DailyWordProgress {
  date: string
  guesses: string[]
  phase: WordPuzzlePhase
}

export interface DailyWordState {
  date: string
  answer: string
  guesses: WordGuess[]
  draft: string
  phase: WordPuzzlePhase
  message: string
}

export type DailyWordAction =
  | { type: 'letter'; letter: string }
  | { type: 'backspace' }
  | { type: 'submit' }

