const VALID_WORDS = new Set([...ANSWERS, ...EXTRA_GUESSES].filter((word) => word.length === WORD_LENGTH))
export const FIVE_LETTER_WORD_LIST: readonly string[] = [...VALID_WORDS]
const DAY_MS = 86_400_000
const GAME_EPOCH = Date.parse(`${WORD_GAME_START_DATE}T00:00:00.000Z`)

export function createDailyWordState(date: string, guesses: string[] = []): DailyWordState {
  if (!isUtcDateKey(date)) throw new RangeError('Date must be a real UTC date in YYYY-MM-DD format.')
  const answer = dailyWordForDate(date)
  const validGuesses = guesses.filter((guess) => VALID_WORDS.has(guess) && guess.length === WORD_LENGTH).slice(0, WORD_GUESS_LIMIT)
  const won = validGuesses.includes(answer)
  const phase: WordPuzzlePhase = won ? 'won' : validGuesses.length >= WORD_GUESS_LIMIT ? 'lost' : 'playing'
  return {
    date,
    answer,
    guesses: validGuesses.map((word) => ({ word, marks: scoreGuess(answer, word) })),
    draft: '',
    phase,
    message: phase === 'won'
      ? `Solved in ${validGuesses.length} ${validGuesses.length === 1 ? 'guess' : 'guesses'}. Come back tomorrow for a new word.`
      : phase === 'lost'
        ? `The word was ${answer}. Come back tomorrow for a new word.`
        : validGuesses.length > 0
          ? 'Your guesses are saved in this browser.'
          : 'Find the five-letter word in six guesses.',
  }
}

export function dailyWordForDate(date: string): string {
  if (!isUtcDateKey(date)) throw new RangeError('Date must be a real UTC date in YYYY-MM-DD format.')
  const day = Math.floor((Date.parse(`${date}T00:00:00.000Z`) - GAME_EPOCH) / DAY_MS)
  return ANSWERS[((day % ANSWERS.length) + ANSWERS.length) % ANSWERS.length]!
}

export function isValidWordGuess(word: string): boolean {
  return VALID_WORDS.has(word)
}

export function scoreGuess(answer: string, guess: string): LetterMark[] {
  const marks: LetterMark[] = Array(WORD_LENGTH).fill('absent')
  const unmatched = new Map<string, number>()

  for (let index = 0; index < WORD_LENGTH; index += 1) {
    if (guess[index] === answer[index]) marks[index] = 'correct'
    else unmatched.set(answer[index]!, (unmatched.get(answer[index]!) ?? 0) + 1)
  }

  for (let index = 0; index < WORD_LENGTH; index += 1) {
    if (marks[index] === 'correct') continue
    const letter = guess[index]!
    const count = unmatched.get(letter) ?? 0
    if (count > 0) {
      marks[index] = 'present'
      unmatched.set(letter, count - 1)
    }
  }

  return marks
}

export function dailyWordReducer(state: DailyWordState, action: DailyWordAction): DailyWordState {
  if (state.phase !== 'playing') return state

  if (action.type === 'letter') {
    const letter = action.letter.toUpperCase()
    if (!/^[A-Z]$/.test(letter) || state.draft.length >= WORD_LENGTH) return state
    return { ...state, draft: `${state.draft}${letter}`, message: 'Keep going, or press Enter when the row is full.' }
  }

  if (action.type === 'backspace') {
    return state.draft ? { ...state, draft: state.draft.slice(0, -1), message: 'Letter removed.' } : state
  }

  if (state.draft.length !== WORD_LENGTH) {
    return { ...state, message: 'The guess needs five letters.' }
  }
  if (!isValidWordGuess(state.draft)) return { ...state, message: 'That word is not in this game’s word list.' }

  const guesses = [...state.guesses, { word: state.draft, marks: scoreGuess(state.answer, state.draft) }]
  const solved = state.draft === state.answer
  const lost = !solved && guesses.length >= WORD_GUESS_LIMIT
  const phase: WordPuzzlePhase = solved ? 'won' : lost ? 'lost' : 'playing'
  return {
    ...state,
    guesses,
    draft: '',
    phase,
    message: solved
      ? `Solved in ${guesses.length} ${guesses.length === 1 ? 'guess' : 'guesses'}. Come back tomorrow for a new word.`
      : lost
        ? `The word was ${state.answer}. Come back tomorrow for a new word.`
        : `${WORD_GUESS_LIMIT - guesses.length} ${WORD_GUESS_LIMIT - guesses.length === 1 ? 'guess' : 'guesses'} left.`,
  }
}

export function getLetterStatuses(guesses: WordGuess[]): Record<string, LetterMark> {
  const status: Record<string, LetterMark> = {}
  const priority: Record<LetterMark, number> = { absent: 0, present: 1, correct: 2 }
  for (const guess of guesses) {
    guess.word.split('').forEach((letter, index) => {
      const mark = guess.marks[index]!
      if (status[letter] === undefined || priority[mark] > priority[status[letter]!]) status[letter] = mark
    })
  }
  return status
}

function isUtcDateKey(date: string): boolean {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return false
  const timestamp = Date.parse(`${date}T00:00:00.000Z`)
  return Number.isFinite(timestamp) && new Date(timestamp).toISOString().slice(0, 10) === date
}
